    [Test]
    public void EventFixturesContainTheSignalingNaNBitPattern()
    {
        if (!FloatingEventInputs.Values(33).Select(BitConverter.SingleToInt32Bits).Contains(0x7f800001))
            throw new InvalidOperationException("The fixture quieted its signaling NaN before the sort.");
    }

