    public void EventsAndElementBitsMatchRecordedContract(string elementType, string algorithm, int n, int custom, bool observed, string expected)
    {
        switch (elementType)
        {
            case "Half": Verify<Half>(algorithm, n, custom, observed, expected); break;
            case "Single": Verify<float>(algorithm, n, custom, observed, expected); break;
            case "Double": Verify<double>(algorithm, n, custom, observed, expected); break;
            default: throw new ArgumentException(elementType);
        }
    }

    static void Verify<T>(string algorithm, int n, int custom, bool observed, string expected)
        where T : unmanaged, IFloatingPointIeee754<T>
    {
        var values = new T[n + 4];
        Array.Fill(values, T.CreateChecked(987));
        FloatingEventInputs.Values(n).Select(static value => T.CreateSaturating(value)).ToArray().CopyTo(values, 2);
        var before = (T[])values.Clone();
        var recorder = new FloatingEventRecorder();
        var comparer = new FloatingEventComparer<T>(custom, recorder);
        if (observed) Run<T, FloatingEventContext>(algorithm, values, n, custom, comparer, new FloatingEventContext(recorder));
        else Run<T, NullContext>(algorithm, values, n, custom, comparer, NullContext.Default);
        var actualHash = recorder.Hash(values);
        var oracle = new FloatingEventComparer<T>(custom, new FloatingEventRecorder());
        var sorted = before.AsSpan(2, n).ToArray().OrderBy(static value => value, oracle).ToArray();
        for (var i = 0; i < n; i++)
            if (oracle.Compare(values[i + 2], sorted[i]) != 0)
                throw new InvalidOperationException($"Wrong recorded comparer order: {algorithm}/{n}/{custom}/{observed}");
        if (!before.Select(FloatingEventInputs.Bits).Order().SequenceEqual(values.Select(FloatingEventInputs.Bits).Order())
            || values[0] != before[0] || values[1] != before[1] || values[^2] != before[^2] || values[^1] != before[^1])
            throw new InvalidOperationException("The recorded sort changed element bits or wrote outside its range.");
        if (actualHash != expected)
            throw new InvalidOperationException($"Event or element-bit contract changed: {algorithm}/{n}/{custom}/{observed}; actual={actualHash}");
    }

    static void Run<T, TContext>(string algorithm, Span<T> values, int n, int custom, FloatingEventComparer<T> comparer, TContext context)
        where T : unmanaged, IFloatingPointIeee754<T>
        where TContext : ISortContext
    {
        switch (algorithm)
        {
            case "QuickSort":
                if (custom == 0) QuickSort.Sort(values, 2, n + 2, context);
                else QuickSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "BinaryInsertionSort":
                if (custom == 0) BinaryInsertionSort.Sort(values, 2, n + 2, context);
                else BinaryInsertionSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "HeapSort":
                if (custom == 0) HeapSort.Sort(values, 2, n + 2, context);
                else HeapSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "MinHeapSort":
                if (custom == 0) MinHeapSort.Sort(values, 2, n + 2, context);
                else MinHeapSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "BottomupHeapSort":
                if (custom == 0) BottomupHeapSort.Sort(values, 2, n + 2, context);
                else BottomupHeapSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "CycleSort":
                if (custom == 0) CycleSort.Sort(values.Slice(2, n), context);
                else CycleSort.Sort(values.Slice(2, n), comparer, context);
                break;
            case "TernaryHeapSort":
                if (custom == 0) TernaryHeapSort.Sort(values, 2, n + 2, context);
                else TernaryHeapSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "SmoothSort":
                if (custom == 0) SmoothSort.Sort(values.Slice(2, n), context);
                else SmoothSort.Sort(values.Slice(2, n), comparer, context);
                break;
            case "TimSort":
                if (custom == 0) TimSort.Sort(values, 2, n + 2, context);
                else TimSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "IntroSort":
                if (custom == 0) IntroSort.Sort(values, 2, n + 2, context);
                else IntroSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "BlockQuickSort":
                if (custom == 0) BlockQuickSort.Sort(values, 2, n + 2, context);
                else BlockQuickSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "PDQSort":
                if (custom == 0) PDQSort.Sort(values, 2, n + 2, context);
                else PDQSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "PDQSortBranchless":
                if (custom == 0) PDQSortBranchless.Sort(values, 2, n + 2, context);
                else PDQSortBranchless.Sort(values, 2, n + 2, comparer, context);
                break;
            case "StdSort":
                if (custom == 0) StdSort.Sort(values, 2, n + 2, context);
                else StdSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "PowerSort":
                if (custom == 0) PowerSort.Sort(values, 2, n + 2, context);
                else PowerSort.Sort(values, 2, n + 2, comparer, context);
                break;
            case "HeapFallback":
                if (custom == 0)
                {
                    var span = new SortSpan<T, ComparableComparer<T>, TContext>(values, context, default, 7, 11);
                    HeapSort.SortFallbackCore(span, 2, n + 2);
                }
                else
                {
                    var span = new SortSpan<T, FloatingEventComparer<T>, TContext>(values, context, comparer, 7, 11);
                    HeapSort.SortFallbackCore(span, 2, n + 2);
                }
                break;
            default: throw new ArgumentException(algorithm);
        }
    }
}

static class FloatingEventInputs
{
    public static float[] Values(int n)
    {
        float[] edges = [FromBits(0x7fc00001), -0f, 0f, -1f, 1f,
            FromBits(unchecked((int)0xffc00002)), float.NegativeInfinity,
            float.PositiveInfinity, FromBits(0x7f800001), float.Epsilon, -float.Epsilon];
        return Enumerable.Range(0, n).Select(i => edges[(i * 7 + n) % edges.Length]).ToArray();
    }
    // Keep the signaling-NaN bit pattern out of constant folding.
    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    static float FromBits(int bits) => BitConverter.Int32BitsToSingle(bits);
    public static string Bits<T>(T value) => value switch
    {
        float f => BitConverter.SingleToInt32Bits(f).ToString("X8"),
        double d => BitConverter.DoubleToInt64Bits(d).ToString("X16"),
        Half h => BitConverter.HalfToUInt16Bits(h).ToString("X4"),
        int i => i.ToString("X8"),
        _ => throw new NotSupportedException(typeof(T).Name)
    };
}
sealed class FloatingEventRecorder
{
    public readonly List<string> Events = [];
    public string Hash<T>(T[] values)
        => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(string.Join("\n", Events) + "\nvalues:" + string.Join(",", values.Select(FloatingEventInputs.Bits)))));
}
sealed class FloatingEventComparer<T>(int kind, FloatingEventRecorder recorder) : IComparer<T> where T : unmanaged, IFloatingPointIeee754<T>
{
    public int Compare(T x, T y)
    {
        recorder.Events.Add($"call:{FloatingEventInputs.Bits(x)}:{FloatingEventInputs.Bits(y)}");
        var result = kind switch
        {
            1 => y.CompareTo(x),
            2 when T.IsNaN(x) != T.IsNaN(y) => T.IsNaN(x) ? 1 : -1,
            2 when x == T.Zero && y == T.Zero && T.IsNegative(x) != T.IsNegative(y) => T.IsNegative(x) ? -1 : 1,
            _ => x.CompareTo(y)
        };
        return result < 0 ? int.MinValue : result > 0 ? int.MaxValue : 0;
    }
}

sealed class FloatingEventContext(FloatingEventRecorder recorder) : SortAlgorithm.Contexts.ISortContext
{
    public void OnCompare(int i, int j, int result, int bi, int bj) => recorder.Events.Add($"c:{i}:{j}:{result}:{bi}:{bj}");
    public void OnSwap(int i, int j, int buffer) => recorder.Events.Add($"s:{i}:{j}:{buffer}");
    public void OnIndexRead(int i, int buffer) => recorder.Events.Add($"r:{i}:{buffer}");
    public void OnIndexWrite(int i, int buffer) => recorder.Events.Add($"w:{i}:{buffer}");
    public void OnIndexWrite<TValue>(int i, int buffer, TValue value) => recorder.Events.Add($"w:{i}:{buffer}:{FloatingEventInputs.Bits(value)}");
    public void OnRangeCopy(int i, int j, int length, int bi, int bj) => recorder.Events.Add($"copy:{i}:{j}:{length}:{bi}:{bj}");
    public void OnRangeCopy<TValue>(int i, int j, int length, int bi, int bj, ReadOnlySpan<TValue> values)
    {
        recorder.Events.Add($"copy:{i}:{j}:{length}:{bi}:{bj}");
        foreach (var value in values) recorder.Events.Add($"copyvalue:{FloatingEventInputs.Bits(value)}");
    }
    public void OnPhase(SortAlgorithm.Contexts.SortPhase phase, int a = 0, int b = 0, int c = 0) => recorder.Events.Add($"phase:{(int)phase}:{a}:{b}:{c}");
    public void OnRole(int i, int buffer, SortAlgorithm.Contexts.RoleType role) => recorder.Events.Add($"role:{i}:{buffer}:{(int)role}");
    public void OnLink(int i, int j, int buffer, SortAlgorithm.Contexts.LinkSide side) => recorder.Events.Add($"link:{i}:{j}:{buffer}:{(int)side}");
}
